class Logger {
    unordered_map<string, int> lastPrinted;
public:
    Logger() {}
    bool shouldPrintMessage(int timestamp, string message) {
        if (!lastPrinted.count(message) || timestamp - lastPrinted[message] >= 10) {
            lastPrinted[message] = timestamp;
            return true;
        }
        return false;
    }
};

snippets.java:
class Logger {
    private Map<String, Integer> lastPrinted = new HashMap<>();
    public Logger() {}
    public boolean shouldPrintMessage(int timestamp, String message) {
        if (!lastPrinted.containsKey(message) || timestamp - lastPrinted.get(message) >= 10) {
            lastPrinted.put(message, timestamp);
            return true;
        }
        return false;
    }
}

