var Logger = function() {
    this.lastPrinted = new Map();
};
Logger.prototype.shouldPrintMessage = function(timestamp, message) {
    if (!this.lastPrinted.has(message) || timestamp - this.lastPrinted.get(message) >= 10) {
        this.lastPrinted.set(message, timestamp);
        return true;
    }
    return false;
};
